// lib/industrialClusters.ts
init_step04_supabase_stub();
var TABLE = "industrial_clusters";
var COLS = "id,name,slug,country,country_code,region,city,industry,industry_tags,description,seo_title,seo_description,is_published,sort_order,created_at,updated_at";
async function listPublishedClusters() {
  const db = createAdminClient();
  if (!db) return [];
  try {
    const { data, error } = await db.from(TABLE).select(COLS).eq("is_published", true).order("sort_order", { ascending: true }).order("name", { ascending: true });
    if (error) {
      console.error("[industrialClusters] list published failed", error.message);
      return [];
    }
    return data ?? [];
  } catch (e) {
    console.error("[industrialClusters] list published exception", e);
    return [];
  }
}
async function getPublishedClusterBySlug(slug) {
  if (!slug) return null;
  const db = createAdminClient();
  if (!db) return null;
  try {
    const { data, error } = await db.from(TABLE).select(COLS).eq("slug", slug).eq("is_published", true).maybeSingle();
    if (error) {
      console.error("[industrialClusters] get by slug failed", error.message);
      return null;
    }
    return data ?? null;
  } catch (e) {
    console.error("[industrialClusters] get by slug exception", e);
    return null;
  }
}

